import apiClient from './client'
import type { Page, PageParams } from './page'

export interface AlertEventRead {
  id: number
  rule_id: number
  node_id: string
  severity: string
  message?: string | null
  labels?: Record<string, unknown> | null
  fired_at: string
}

export interface AlertStats {
  dedup_window_seconds: number
  active_silence_count: number
  total_silence_count: number
  inhibition_count: number
  checked_at: string
}

export interface AlertEventFilters {
  rule_id?: number
  node_id?: string
  severity?: string
}

export type AlertEventListParams = PageParams & AlertEventFilters

export async function getAlertEvents(params?: AlertEventListParams): Promise<Page<AlertEventRead>> {
  const response = await apiClient.get<Page<AlertEventRead>>('/v1/alerts', { params })
  return response.data
}

export async function getAlertStats(): Promise<AlertStats> {
  const response = await apiClient.get<AlertStats>('/v1/alerts/stats')
  return response.data
}
