<template>
  <div class="page-alert-history">
    <div class="page-header">
      <h2>{{ t('alerts.history.title') }}</h2>
    </div>

    <el-card>
      <el-form :inline="true" :model="filters" class="filter-form">
        <el-form-item :label="t('alerts.history.ruleId')">
          <el-input-number v-model="filters.rule_id" :min="1" :placeholder="t('alerts.history.ruleId')" :controls="false" />
        </el-form-item>
        <el-form-item :label="t('nodes.nodeId')">
          <el-input v-model="filters.node_id" :placeholder="t('nodes.nodeId')" clearable />
        </el-form-item>
        <el-form-item :label="t('common.severityLabel')">
          <el-select v-model="filters.severity" :placeholder="t('common.all')" clearable style="width: 120px">
            <el-option :label="t('common.critical')" value="critical" />
            <el-option :label="t('common.warning')" value="warning" />
            <el-option :label="t('common.info')" value="info" />
          </el-select>
        </el-form-item>
        <el-form-item>
          <el-button type="primary" @click="onSearch">{{ t('common.query') }}</el-button>
          <el-button @click="onReset">{{ t('common.reset') }}</el-button>
        </el-form-item>
      </el-form>

      <DataTable
        v-model:current-page="page"
        v-model:page-size="pageSize"
        :data="events"
        :loading="loading"
        :server-side="true"
        :total="total"
      >
        <el-table-column prop="id" label="ID" width="80" />
        <el-table-column prop="rule_id" :label="t('alerts.history.ruleId')" width="100" />
        <el-table-column prop="node_id" :label="t('nodes.nodeId')" min-width="140" />
        <el-table-column prop="severity" :label="t('common.severityLabel')" width="100">
          <template #default="{ row }">
            <StatusTag :status="row.severity" type="severity" />
          </template>
        </el-table-column>
        <el-table-column prop="message" :label="t('common.message')" min-width="200" show-overflow-tooltip />
        <el-table-column prop="fired_at" :label="t('alerts.history.firedAt')" width="180" />
      </DataTable>
    </el-card>
  </div>
</template>

<script setup lang="ts">
import { ref, watch } from 'vue'
import { useI18n } from 'vue-i18n'
import { getAlertEvents, type AlertEventRead } from '@/api/alerts'
import { useListQuery } from '@/composables/useListQuery'
import StatusTag from '@/components/common/StatusTag.vue'
import DataTable from '@/components/common/DataTable.vue'
import { showError } from '@/utils/error'

const { t } = useI18n()

const events = ref<AlertEventRead[]>([])
const total = ref(0)
const loading = ref(false)

const { page, pageSize, filters, resetFilters } = useListQuery({
  defaults: {
    rule_id: undefined as number | undefined,
    node_id: '',
    severity: '',
  },
  parse: (q) => ({
    rule_id: q.rule_id ? Number(q.rule_id) : undefined,
    node_id: (q.node_id as string) || '',
    severity: (q.severity as string) || '',
  }),
  serialize: (f) => ({
    rule_id: f.rule_id ? String(f.rule_id) : undefined,
    node_id: f.node_id || undefined,
    severity: f.severity || undefined,
  }),
})

async function loadEvents() {
  loading.value = true
  try {
    const response = await getAlertEvents({
      page: page.value,
      page_size: pageSize.value,
      rule_id: filters.rule_id,
      node_id: filters.node_id || undefined,
      severity: filters.severity || undefined,
    })
    events.value = response.items
    total.value = response.total
  } catch (error) {
    showError(error, t('alerts.history.loadFailed'))
  } finally {
    loading.value = false
  }
}

function onSearch() {
  page.value = 1
}

function onReset() {
  resetFilters()
}

watch(
  () => ({ page: page.value, pageSize: pageSize.value, filters }),
  loadEvents,
  { deep: true, immediate: true }
)
</script>

<style scoped>
.page-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 20px;
}

.page-header h2 {
  margin: 0;
}

.filter-form {
  margin-bottom: 16px;
}
</style>
